import requests
queries=['(oligomeric OR monomeric) silica aluminum absorption','silicon aluminum absorption human volunteer silicic acid','aluminium absorption orthosilicic acid human','silica oligomeric aluminium bioavailability']
for q in queries:
 r=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi',params={'db':'pubmed','term':q,'retmode':'json','retmax':30},timeout=20)
 d=r.json()['esearchresult']; ids=d['idlist']; print('\nQUERY',q,'COUNT',d['count'])
 if ids:
  s=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi',params={'db':'pubmed','id':','.join(ids),'retmode':'json'},timeout=20).json()['result']
  for i in ids:
   z=s[i]; print(i,z.get('title'),z.get('pubdate'))

import requests,xml.etree.ElementTree as ET
pid='10731501'
u='https://eutils.ncbi.nlm.nih.gov/entrez/eutils/efetch.fcgi'
r=requests.get(u,params={'db':'pubmed','id':pid,'rettype':'abstract','retmode':'xml'},timeout=20)
root=ET.fromstring(r.text)
for el in root.findall('.//ArticleTitle'): print('TITLE:', ''.join(el.itertext()))
for el in root.findall('.//Abstract/AbstractText'): print('ABSTRACT:',el.get('Label',''),''.join(el.itertext()))
for el in root.findall('.//Journal/Title'): print('JOURNAL:',el.text)
for el in root.findall('.//PubDate'): print('DATE:', ' '.join(x.text or '' for x in el))
